import { test, expect } from '@playwright/test';

test.describe('Popover Toggle on Button Click', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <html>
        <head>
          <style>
            body {
              font-family: Arial, sans-serif;
              padding: 20px;
            }
            .popover {
              display: none;
              position: absolute;
              background-color: white;
              border: 1px solid #ccc;
              border-radius: 4px;
              padding: 16px;
              box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
              z-index: 1000;
              min-width: 200px;
              top: 50px;
              left: 0;
            }
            .popover.visible {
              display: block;
            }
            .toggle-button {
              padding: 8px 16px;
              background-color: #007bff;
              color: white;
              border: none;
              border-radius: 4px;
              cursor: pointer;
              font-size: 14px;
            }
            .toggle-button:hover {
              background-color: #0056b3;
            }
            .popover-content {
              color: #333;
              font-size: 14px;
            }
          </style>
        </head>
        <body>
          <button class="toggle-button" id="popover-trigger">Toggle Popover</button>
          <div class="popover" id="popover-content" role="dialog" aria-label="Popover">
            <div class="popover-content">
              This is a popover content. Click the button to toggle visibility.
            </div>
          </div>
          <script>
            const button = document.getElementById('popover-trigger');
            const popover = document.getElementById('popover-content');
            button.addEventListener('click', function() {
              popover.classList.toggle('visible');
            });
          </script>
        </body>
      </html>
    `);
  });

  test('should display popover when button is clicked', async ({ page }) => {
    const popoverButton = page.getByRole('button', { name: 'Toggle Popover' });
    const popover = page.getByRole('dialog', { name: 'Popover' });

    // Verify popover is initially hidden
    await expect(popover).not.toBeVisible();

    // Click button to show popover
    await popoverButton.click();

    // Verify popover is now visible
    await expect(popover).toBeVisible();
    await expect(popover).toContainText('This is a popover content');
  });

  test('should hide popover when button is clicked again', async ({ page }) => {
    const popoverButton = page.getByRole('button', { name: 'Toggle Popover' });
    const popover = page.getByRole('dialog', { name: 'Popover' });

    // Click button to show popover
    await popoverButton.click();
    await expect(popover).toBeVisible();

    // Click button again to hide popover
    await popoverButton.click();
    await expect(popover).not.toBeVisible();
  });

  test('should toggle popover multiple times', async ({ page }) => {
    const popoverButton = page.getByRole('button', { name: 'Toggle Popover' });
    const popover = page.getByRole('dialog', { name: 'Popover' });

    // First toggle - show
    await popoverButton.click();
    await expect(popover).toBeVisible();

    // Second toggle - hide
    await popoverButton.click();
    await expect(popover).not.toBeVisible();

    // Third toggle - show
    await popoverButton.click();
    await expect(popover).toBeVisible();

    // Fourth toggle - hide
    await popoverButton.click();
    await expect(popover).not.toBeVisible();
  });

  test('should have correct popover content visible', async ({ page }) => {
    const popoverButton = page.getByRole('button', { name: 'Toggle Popover' });
    const popoverContent = page.getByText('This is a popover content');

    // Content should not be visible initially
    await expect(popoverContent).not.toBeVisible();

    // Click to show popover
    await popoverButton.click();

    // Content should now be visible
    await expect(popoverContent).toBeVisible();
  });
});
